package com.troday.api.entity;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="chat_messages",uniqueConstraints=@UniqueConstraint(columnNames={"sender_id","client_message_key"})) public class ChatMessage {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="conversation_id",nullable=false) private Long conversationId; @Column(name="sender_id",nullable=false) private Long senderId; @Column(name="client_message_key",nullable=false) private String clientMessageKey; @Column(name="message_type",nullable=false) private String messageType="TEXT"; @Lob private String content; @Column(name="shared_post_id") private Long sharedPostId; @Column(name="sent_at",nullable=false) private LocalDateTime sentAt;
 public Long getId(){return id;} public Long getConversationId(){return conversationId;} public void setConversationId(Long v){conversationId=v;} public Long getSenderId(){return senderId;} public void setSenderId(Long v){senderId=v;} public String getClientMessageKey(){return clientMessageKey;} public void setClientMessageKey(String v){clientMessageKey=v;} public String getMessageType(){return messageType;} public void setMessageType(String v){messageType=v;} public String getContent(){return content;} public void setContent(String v){content=v;} public Long getSharedPostId(){return sharedPostId;} public void setSharedPostId(Long v){sharedPostId=v;} public LocalDateTime getSentAt(){return sentAt;} public void setSentAt(LocalDateTime v){sentAt=v;}
}
